(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.28)*18 + Math.sin(x*0.02+t*0.32)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8 + Math.cos((x-y)*0.012-t*0.18)*6;
  const w2y = Math.cos((x-y)*0.011+t*0.17)*8 + Math.sin((x+y)*0.013-t*0.2)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*40, 0.05, 2.4, 1.15],
    [200+Math.sin(t*0.25+6)*110, 10+Math.cos(t*0.45+5)*30, 0.13, 1.6, 0.95],
    [300+Math.cos(t*0.7+3)*90, 200+Math.sin(t*0.5+2)*60, 0.075, 2.2, 1.05]
  ];
  let aS=0, iS=0, mS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    aS += wave*w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5)*w;
    mS += Math.sin(d*f*0.4 - t*sp*0.3 + 3.0)*w*0.5;
  }
  const n = 10;
  const act = aS/n, inh = iS/n, mod = mS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = Math.sin(dist*0.03+ang*2-t*0.8)*Math.cos(dist*0.07-ang*5+t*1.8)*0.25;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2 = Math.tanh((Math.cos(sx*0.08+t*0.3)*Math.sin(sy*0.09-t*0.2) + Math.sin(sx*0.12-sy*0.07+t*0.5))*1.2)*0.2;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + spiral2 + mod*0.4)*2.0);
  const blend = reaction*0.6 + cell*0.2 + cell2*0.2;
  const v = blend*0.5+0.5;
  const dx = Math.abs(blend - Math.tanh((act+0.5 - inh*0.7 + bg*0.3 + spiral)*2.0));
  const dy = Math.abs(blend - Math.tanh((act - inh*0.7+0.5 + bg*0.3 + spiral)*2.0));
  const edge = Math.min(1.0, Math.sqrt(dx*dx+dy*dy)*8.0);
  const glow = Math.exp(-edge*3.0)*0.4;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.2 + glow*0.3;
  const pal = [
    [5,10,45],[10,30,75],[12,55,95],[15,85,110],[20,120,120],
    [60,155,110],[140,185,80],[210,195,55],[225,150,60],
    [215,105,65],[185,65,70],[140,40,75],[90,25,65],[45,15,55],[5,10,45]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const highlight = edge > 0.5 ? (edge-0.5)*0.5 : 0;
  return [
    Math.min(255, (r0*lum + highlight*80)|0),
    Math.min(255, (g0*lum + highlight*90)|0),
    Math.min(255, (b0*lum + highlight*60)|0)
  ];
}
